CREATE TABLE customers(id varchar(128) PRIMARY KEY, display_name varchar(255) NOT NULL, status varchar(20) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts(id varchar(128) PRIMARY KEY, customer_id varchar(128) NOT NULL REFERENCES customers(id) ON DELETE RESTRICT, currency char(3) NOT NULL DEFAULT 'JOD', available_balance numeric(19,3) NOT NULL CHECK(available_balance>=0), opening_balance numeric(19,3) NOT NULL CHECK(opening_balance>=0), status varchar(20) NOT NULL CHECK(status IN ('ACTIVE','FROZEN','CLOSED')), receive_allowed boolean NOT NULL DEFAULT true, debit_limit numeric(19,3) NOT NULL DEFAULT 10000.000 CHECK(debit_limit>0), version bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE account_permissions(account_id varchar(128) REFERENCES accounts(id) ON DELETE RESTRICT, principal varchar(128) NOT NULL, can_debit boolean NOT NULL DEFAULT false, can_receive boolean NOT NULL DEFAULT false, PRIMARY KEY(account_id,principal));
CREATE TABLE payments(payment_id uuid PRIMARY KEY, from_account_id varchar(128) NOT NULL, to_account_id varchar(128) NOT NULL, amount numeric(19,3) NOT NULL CHECK(amount>0), currency char(3) NOT NULL DEFAULT 'JOD', instruction_date timestamptz NOT NULL, purpose varchar(255) NOT NULL, notes varchar(1000), payload_fingerprint char(64) NOT NULL, status varchar(20) NOT NULL CHECK(status IN ('PROCESSING','COMPLETED','REJECTED')), rejection_code varchar(64), created_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, requested_by varchar(128) NOT NULL, correlation_id uuid NOT NULL);
-- Payment account identifiers deliberately have no FK: durable business rejections may reference missing accounts.
CREATE INDEX payments_source_idx ON payments(from_account_id,created_at); CREATE INDEX payments_destination_idx ON payments(to_account_id,created_at); CREATE INDEX payments_created_idx ON payments(created_at);
CREATE TABLE ledger_entries(id bigserial PRIMARY KEY, payment_id uuid NOT NULL REFERENCES payments(payment_id) ON DELETE RESTRICT, account_id varchar(128) NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT, entry_type varchar(6) NOT NULL CHECK(entry_type IN ('DEBIT','CREDIT')), signed_amount numeric(19,3) NOT NULL, balance_after numeric(19,3) NOT NULL CHECK(balance_after>=0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(payment_id,entry_type), CHECK((entry_type='DEBIT' AND signed_amount<0) OR (entry_type='CREDIT' AND signed_amount>0)));
CREATE INDEX ledger_account_idx ON ledger_entries(account_id,id);
CREATE FUNCTION protect_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable ledger'; END $$;
CREATE TRIGGER immutable_ledger BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION protect_ledger();
CREATE FUNCTION protect_payment() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' OR OLD.status IN ('COMPLETED','REJECTED') THEN RAISE EXCEPTION 'Immutable payment'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_payment BEFORE UPDATE OR DELETE ON payments FOR EACH ROW EXECUTE FUNCTION protect_payment();
CREATE FUNCTION check_payment_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE n int; total numeric; final_status text; BEGIN SELECT status INTO final_status FROM payments WHERE payment_id=NEW.payment_id; IF final_status='COMPLETED' THEN SELECT count(*),coalesce(sum(signed_amount),0) INTO n,total FROM ledger_entries WHERE payment_id=NEW.payment_id; IF n<>2 OR total<>0 THEN RAISE EXCEPTION 'Unbalanced payment'; END IF; ELSIF final_status='PROCESSING' THEN RAISE EXCEPTION 'Unfinished payment'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER balanced_payment AFTER INSERT OR UPDATE ON payments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_payment_ledger();
CREATE VIEW reconciliation_issues AS SELECT 'PAYMENT' AS kind, p.payment_id::text AS identifier FROM payments p LEFT JOIN ledger_entries l USING(payment_id) WHERE p.status='COMPLETED' GROUP BY p.payment_id HAVING count(l.id)<>2 OR coalesce(sum(l.signed_amount),0)<>0 UNION ALL SELECT 'ACCOUNT',a.id FROM accounts a LEFT JOIN ledger_entries l ON l.account_id=a.id GROUP BY a.id HAVING a.available_balance<>a.opening_balance+coalesce(sum(l.signed_amount),0);
CREATE TABLE request_limits(principal varchar(128) PRIMARY KEY, minute timestamptz NOT NULL,count bigint NOT NULL);
